INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 21, 'theory', 'Quiz: subprocess and parsing output');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 21, 0, 'Why is subprocess.run(["lvs", vg]) safer than subprocess.run(f"lvs {vg}", shell=True) when vg comes from a user?', '["A list runs faster, so there is no time to attack", "A list automatically checks the name against the LVM rules", "No shell is involved, and the content of vg reaches the program as one argument", "A list forbids the program to read standard input"]', 2, 'Without a shell, semicolons and spaces in the name mean nothing. A name starting with a hyphen is still taken as an option by the program, so names must be validated too.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 21, 1, 'What do you get if you run a nonexistent program like this: subprocess.run(["nosuchtool"])?', '["A FileNotFoundError exception", "A result with returncode 127", "A result with returncode -1", "A hang until the timeout"]', 0, 'Without a shell Python itself cannot start the file and raises an exception (an OSError subclass). You would see code 127 only through shell=True, where the shell reports it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 21, 2, 'You passed env={"LC_ALL": "C"} and the command stopped finding its libraries and programs. Why?', '["LC_ALL=C forbids loading libraries", "The env parameter works only together with shell=True", "The variable value must be passed as bytes", "env replaces the whole environment, so PATH and the other variables are gone"]', 3, 'Copy the current environment and add your own variables: {**os.environ, "LC_ALL": "C"}.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 21, 3, 'What is true of the output of lvs --reportformat json in the plain json mode (not json_std)?', '["Sizes and percentages are JSON numbers and can be compared directly", "Values are strings, sizes included; an empty field is an empty string", "Hidden volumes are always included in the output", "Sizes are always given in bytes with no suffix"]', 1, 'Numbers in quotes are a trait of the json mode; json_std gives real numbers. Sizes in bytes must be requested (--units b --nosuffix), hidden volumes with -a.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 21, 4, 'In the df -P output the mount point /mnt/My Disk contains a space. How do you parse the line reliably?', '["line.split() and take the last element", "line.split(\" \") and join the tail with a space", "line.split(None, 5): the sixth element is the rest of the line", "Replace spaces in the output with underscores before parsing"]', 2, 'The first five fields contain no spaces and the mount point comes last. Limiting the number of splits keeps it intact, repeated spaces included.');
